    bad = 0
    for scn in spec["scenarios"]:
        results, tree = run_scenario(repo, spec, scn)
        problems = compare(scn, results, tree, scn["expected"])
        if problems:
            bad += 1
            print(f"FAIL scenario {scn['name']!r}:")
            for p in problems:
